def test_landfall_self_keywords_stun_and_next_untap_prevention():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot")
    whiptail={**card(855,"Belligerent Whiptail","Creature — Wurm","","4","2"),"oracle_text":"Landfall — Whenever a land you control enters, this creature gains first strike until end of turn.","instance_id":"whiptail","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};kraken={**card(856,"Grappling Kraken","Creature — Kraken","","5","6"),"oracle_text":"Landfall — Whenever a land you control enters, tap target creature an opponent controls and put a stun counter on it.","instance_id":"kraken","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};guardian={**card(857,"Guardian of Tazeem","Creature — Sphinx","","4","5"),"oracle_text":"Flying\nLandfall — Whenever a land you control enters, tap target creature an opponent controls. If that land is an Island, that creature doesn't untap during its controller's next untap step.","instance_id":"guardian","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};victim={**card(858,"Untap Victim","Creature — Soldier","","2","2"),"instance_id":"untap-victim","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"].extend([whiptail,kraken,guardian]);bot["battlefield"].append(victim)
    land={**card(859,"Trigger Island","Basic Land — Island"),"instance_id":"trigger-island","owner_id":"player","controller_id":"player"};_enter_battlefield(state,player,[land],"hand")
    for _ in range(2):state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":"untap-victim"})
    while state["stack"]:state=perform_action(state,"player",{"type":"resolve"})
    player=next(p for p in state["players"] if p["id"]=="player");victim=next(card for card in next(p for p in state["players"] if p["id"]=="bot")["battlefield"] if card["instance_id"]=="untap-victim");whiptail=next(card for card in player["battlefield"] if card["instance_id"]=="whiptail");assert "first strike" in whiptail["temporary_keywords"] and victim["counters"]["stun"]==1 and victim["skip_untap_steps"]==1
    assert not _set_tapped(state,[victim],False,"bot","untap_step") and victim["counters"]["stun"]==0 and victim["tapped"]
    assert not _set_tapped(state,[victim],False,"bot","untap_step") and "skip_untap_steps" not in victim and victim["tapped"]
    assert _set_tapped(state,[victim],False,"bot","untap_step") and not victim["tapped"]


def test_landfall_base_stats_power_and_counter_doubling():
    def resolve_landfall(source:dict,target:dict|None=None,land_count:int=0)->tuple[dict,dict]:
        state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[source]+([target] if target else [])+[{**card(860+index,f"Existing Land {index}","Basic Land — Forest"),"instance_id":f"existing-land-{index}","owner_id":"player","controller_id":"player"} for index in range(land_count)];land={**card(870,"Fresh Land","Basic Land — Island"),"instance_id":"fresh-land","owner_id":"player","controller_id":"player"};_enter_battlefield(state,player,[land],"hand")
        if target:state=perform_action(state,"player",{"type":"choose_trigger_target","target_id":target["instance_id"]})
        state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");return state,next(card for card in player["battlefield"] if card["instance_id"]==(target or source)["instance_id"])
    genemorph={**card(871,"Genemorph Imago","Creature — Shapeshifter","","3","3"),"oracle_text":"Landfall — Whenever a land you control enters, target creature has base power and toughness 3/3 until end of turn. If you control six or more lands, that creature has base power and toughness 6/6 until end of turn instead.","instance_id":"genemorph","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};target={**card(872,"Stat Target","Creature — Beast","","2","4"),"instance_id":"stat-target","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};state,changed=resolve_landfall(genemorph,target,5);assert _parse_stats(changed,state)==(6,6)
    meditator={**card(873,"Mirkwood Meditator","Creature — Elf","","1","4"),"oracle_text":"Landfall — Whenever a land you control enters, you may have this creature's base power and toughness become 4/2 until end of turn.","instance_id":"meditator","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};state,changed=resolve_landfall(meditator);assert _parse_stats(changed,state)==(4,2)
    harmonizer={**card(874,"Mightform Harmonizer","Creature — Mutant","","2","3"),"oracle_text":"Landfall — Whenever a land you control enters, double the power of target creature you control until end of turn.","instance_id":"harmonizer","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};target={**target,"instance_id":"power-target","power":"3","toughness":"3"};state,changed=resolve_landfall(harmonizer,target);assert _parse_stats(changed,state)==(6,3)
    hydra={**card(875,"Mossborn Hydra","Creature — Hydra","","0","0"),"oracle_text":"Trample\nThis creature enters with a +1/+1 counter on it.\nLandfall — Whenever a land you control enters, double the number of +1/+1 counters on this creature.","instance_id":"mossborn","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{"+1/+1":3},"summoning_sick":False};_,changed=resolve_landfall(hydra);assert changed["counters"]["+1/+1"]==6


