        state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");player["battlefield"]=[source]+([target] if target else []);land={**card(878,"Utility Land","Basic Land — Forest"),"instance_id":"utility-land","owner_id":"player","controller_id":"player"};_enter_battlefield(state,player,[land],"hand")
