def test_city_blessing_controls_tribal_static_bonuses_and_unblockable_text():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");dryad={**card(2690,"Tendershoot Dryad","Creature — Dryad","","2","2"),"oracle_text":"Ascend\nSaprolings you control get +2/+2 as long as you have the city's blessing.","instance_id":"tendershoot-dryad","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};saproling={**card(2691,"Saproling Token","Token Creature — Saproling","","1","1"),"instance_id":"blessed-saproling","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False,"token":True};scoundrel={**card(2692,"Slippery Scoundrel","Creature — Human Pirate","","2","2"),"oracle_text":"Ascend\nAs long as you have the city's blessing, this creature has hexproof and can't be blocked.","keywords":["Hexproof"],"instance_id":"slippery-scoundrel","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};blocker={**card(2693,"City Blocker","Creature — Soldier","","2","2"),"instance_id":"city-blocker","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[dryad,saproling,scoundrel];bot["battlefield"]=[blocker];assert _parse_stats(saproling,state)==(1,1) and _can_block_pair(state,scoundrel,blocker) and not _has_keyword(scoundrel,"Hexproof")
    player["city_blessing"]=True;dryad["controller_city_blessing"]=saproling["controller_city_blessing"]=scoundrel["controller_city_blessing"]=True;assert _parse_stats(saproling,state)==(3,3) and not _can_block_pair(state,scoundrel,blocker) and _has_keyword(scoundrel,"Hexproof")


def test_city_blessing_gates_attack_and_combat_damage_triggers():
    state=kept_game();state["phase"]="combat";player=next(p for p in state["players"] if p["id"]=="player");griffin={**card(2700,"Resplendent Griffin","Creature — Griffin","","2","2"),"oracle_text":"Flying\nAscend\nWhenever this creature attacks, if you have the city's blessing, put a +1/+1 counter on it.","instance_id":"resplendent-griffin","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};brawler={**card(2701,"Deadeye Brawler","Creature — Human Pirate","","2","4"),"oracle_text":"Deathtouch\nAscend\nWhenever this creature deals combat damage to a player, if you have the city's blessing, draw a card.","instance_id":"deadeye-brawler","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[griffin,brawler];state["combat"]["attackers"]=["resplendent-griffin"];_queue_triggers(state,"attackers_declared",None,player);assert not state["stack"]
    player["city_blessing"]=True;griffin["controller_city_blessing"]=brawler["controller_city_blessing"]=True;_queue_triggers(state,"attackers_declared",None,player);assert len(state["stack"])==1;state=perform_action(state,"player",{"type":"resolve"});griffin=next(card for card in next(p for p in state["players"] if p["id"]=="player")["battlefield"] if card["instance_id"]=="resplendent-griffin");assert griffin["counters"]["+1/+1"]==1
    player=next(p for p in state["players"] if p["id"]=="player");brawler=next(card for card in player["battlefield"] if card["instance_id"]=="deadeye-brawler");before=len(player["library"]);_queue_triggers(state,"combat_damage_player",brawler,player);assert state["stack"];state=perform_action(state,"player",{"type":"resolve"});assert len(next(p for p in state["players"] if p["id"]=="player")["library"])==before-1


def test_wayward_swordtooth_grants_and_updates_the_additional_land_play():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");swordtooth={**card(2710,"Wayward Swordtooth","Creature — Dinosaur","{2}{G}","5","5"),"oracle_text":"Ascend\nYou may play an additional land on each of your turns.\nThis creature can't attack or block unless you have the city's blessing.","instance_id":"land-swordtooth","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False}
    player["lands_played_this_turn"]=1;player["land_plays_remaining"]=0;_enter_battlefield(state,player,[swordtooth]);assert player["land_plays_remaining"]==1
    _leave_battlefield(state,player,swordtooth,"graveyard");assert player["land_plays_remaining"]==0
    player["battlefield"].append(swordtooth);swordtooth["controller_id"]="player";state["active_player_id"]="bot";_begin_next_turn(state);player=next(p for p in state["players"] if p["id"]=="player");assert state["active_player_id"]=="player" and player["lands_played_this_turn"]==0 and player["land_plays_remaining"]==2


def test_twilight_prophet_reveals_to_hand_and_drains_for_mana_value_when_blessed():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");player["city_blessing"]=True;prophet={**card(2720,"Twilight Prophet","Creature — Vampire Cleric","{2}{B}{B}","2","4"),"oracle_text":"Flying\nAscend\nAt the beginning of your upkeep, if you have the city's blessing, reveal the top card of your library and put that card into your hand. Each opponent loses X life and you gain X life, where X is that card's mana value.","instance_id":"twilight-prophet","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};revealed={**card(2721,"Revealed Dragon","Creature — Dragon","{3}{R}{R}","5","5"),"mana_value":5,"instance_id":"revealed-dragon","owner_id":"player","controller_id":"player"};player["battlefield"]=[prophet];player["library"].append(revealed);_queue_triggers(state,"upkeep",None,player);assert len(state["stack"])==1
    player_life=player["life"];bot_life=bot["life"];state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");assert player["hand"][-1]["instance_id"]=="revealed-dragon" and player["life"]==player_life+5 and bot["life"]==bot_life-5


def test_blessed_golden_demise_kumena_and_anduril_use_their_replacement_effects():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");player["city_blessing"]=True;ally={**card(2730,"Blessed Ally","Creature — Soldier","","2","2"),"instance_id":"demise-ally","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};enemy={**card(2731,"Demise Enemy","Creature — Citizen","","2","2"),"instance_id":"demise-enemy","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[ally];bot["battlefield"]=[enemy];demise={**card(2732,"Golden Demise","Sorcery"),"oracle_text":"Ascend\nAll creatures get -2/-2 until end of turn. If you have the city's blessing, instead only creatures your opponents control get -2/-2 until end of turn.","instance_id":"golden-demise","owner_id":"player","controller_id":"player"};state["stack"]=[{"id":"demise-stack","kind":"spell","card":demise,"controller_id":"player","target_id":None}];state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");assert _parse_stats(player["battlefield"][0],state)==(2,2) and not bot["battlefield"]
    kumena={**card(2733,"Kumena's Awakening","Legendary Enchantment"),"oracle_text":"Ascend\nAt the beginning of your upkeep, each player draws a card. If you have the city's blessing, instead only you draw a card.","instance_id":"kumena-awakening","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"].append(kumena);own_library=len(player["library"]);enemy_library=len(bot["library"]);_queue_triggers(state,"upkeep",None,player);state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");assert len(player["library"])==own_library-1 and len(bot["library"])==enemy_library
    ally=next(card for card in player["battlefield"] if card["instance_id"]=="demise-ally");anduril={**card(2734,"Andúril, Narsil Reforged","Legendary Artifact — Equipment"),"oracle_text":"Ascend\nWhenever equipped creature attacks, put a +1/+1 counter on each creature you control. If you have the city's blessing, put two +1/+1 counters on each creature you control instead.","instance_id":"anduril","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False,"attached_to":"demise-ally"};player["battlefield"].append(anduril);state["combat"]["attackers"]=["demise-ally"];_queue_triggers(state,"attackers_declared",None,player);state=perform_action(state,"player",{"type":"resolve"});ally=next(card for card in next(p for p in state["players"] if p["id"]=="player")["battlefield"] if card["instance_id"]=="demise-ally");assert ally["counters"]["+1/+1"]==2


def test_timestream_navigator_pays_its_bottom_cost_and_schedules_an_extra_turn():
    state=kept_game();state["phase"]="precombat_main";player=next(p for p in state["players"] if p["id"]=="player");player["city_blessing"]=True;lands=[{**card(2740+index,"Island","Basic Land — Island"),"instance_id":f"navigator-island-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(4)];navigator={**card(2744,"Timestream Navigator","Creature — Human Pirate Wizard","{1}{U}","1","1"),"oracle_text":"Ascend\n{2}{U}{U}, {T}, Put Timestream Navigator on the bottom of its owner's library: Take an extra turn after this one. Activate only if you have the city's blessing.","instance_id":"timestream-navigator","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[*lands,navigator];action=next(action for action in legal_actions(state,"player") if action.get("card_id")=="timestream-navigator");state=perform_action(state,"player",action);player=next(p for p in state["players"] if p["id"]=="player");assert navigator not in player["battlefield"] and player["library"][0]["instance_id"]=="timestream-navigator"
    state=perform_action(state,"player",{"type":"resolve"});assert state["extra_turns"]==["player"];turn=state["turn"];_begin_next_turn(state);assert state["turn"]==turn+1 and state["active_player_id"]=="player" and not state["extra_turns"];_begin_next_turn(state);assert state["active_player_id"]=="bot"


def test_expel_from_orazca_offers_and_resolves_the_blessed_top_option():
    def expel_state(blessed:bool):
        state=kept_game();state["phase"]="precombat_main";player=next(p for p in state["players"] if p["id"]=="player");bot=next(p for p in state["players"] if p["id"]=="bot");player["city_blessing"]=blessed;player["battlefield"]=[{**card(2750+index,"Island","Basic Land — Island"),"instance_id":f"expel-island-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];spell={**card(2752,"Expel from Orazca","Instant","{1}{U}"),"oracle_text":"Ascend\nReturn target nonland permanent to its owner's hand. If you have the city's blessing, you may put that permanent on top of its owner's library instead.","instance_id":"expel-orazca","owner_id":"player","controller_id":"player"};target={**card(2753,"Expelled Relic","Artifact"),"instance_id":"expelled-relic","owner_id":"bot","controller_id":"bot","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["hand"]=[spell];bot["battlefield"]=[target];return state
    state=expel_state(True);actions=[action for action in legal_actions(state,"player") if action.get("card_id")=="expel-orazca"];assert len(actions)==2 and sum(bool(action.get("blessing_top")) for action in actions)==1;top=next(action for action in actions if action.get("blessing_top"));state=perform_action(state,"player",{**top,"target_id":"expelled-relic"});assert state["stack"][-1]["blessing_top"];state=perform_action(state,"player",{"type":"resolve"});bot=next(p for p in state["players"] if p["id"]=="bot");assert bot["library"][-1]["instance_id"]=="expelled-relic" and not any(card["instance_id"]=="expelled-relic" for card in bot["hand"])
    state=expel_state(False);actions=[action for action in legal_actions(state,"player") if action.get("card_id")=="expel-orazca"];assert len(actions)==1 and not actions[0].get("blessing_top");state=perform_action(state,"player",{**actions[0],"target_id":"expelled-relic"});state=perform_action(state,"player",{"type":"resolve"});assert next(p for p in state["players"] if p["id"]=="bot")["hand"][-1]["instance_id"]=="expelled-relic"


def test_ocelot_pride_requires_life_gain_and_blessed_copies_only_this_turns_tokens():
    def pride_state(blessed:bool):
        state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");player["city_blessing"]=blessed;pride={**card(2760,"Ocelot Pride","Creature — Cat","{W}","1","1"),"oracle_text":"First strike, lifelink\nAscend\nAt the beginning of your end step, if you gained life this turn, create a 1/1 white Cat creature token. Then if you have the city's blessing, for each token you control that entered this turn, create a token that's a copy of it.","instance_id":"ocelot-pride","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};old={**card(2761,"Old Food","Token Artifact — Food"),"instance_id":"old-food","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False,"token":True,"entered_turn":state["turn"]-1};new={**card(2762,"Fresh Treasure","Token Artifact — Treasure"),"instance_id":"fresh-treasure","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False,"token":True,"entered_turn":state["turn"]};player["battlefield"]=[pride,old,new];return state
    state=pride_state(False);player=next(p for p in state["players"] if p["id"]=="player");_queue_triggers(state,"end_step",None,player);assert not state["stack"];player["life_gain_event_turn"]=state["turn"];player["life_gain_events_this_turn"]=1;_queue_triggers(state,"end_step",None,player);state=perform_action(state,"player",{"type":"resolve"});player=next(p for p in state["players"] if p["id"]=="player");assert sum(card.get("token",False) for card in player["battlefield"])==3 and sum(card["name"]=="Cat Token" for card in player["battlefield"])==1
    state=pride_state(True);player=next(p for p in state["players"] if p["id"]=="player");player["life_gain_event_turn"]=state["turn"];player["life_gain_events_this_turn"]=1;_queue_triggers(state,"end_step",None,player);state=perform_action(state,"player",{"type":"resolve"});tokens=[card for card in next(p for p in state["players"] if p["id"]=="player")["battlefield"] if card.get("token")];assert len(tokens)==5 and sum(card["name"]=="Cat Token" for card in tokens)==2 and sum(card["name"]=="Fresh Treasure" for card in tokens)==2 and sum(card["name"]=="Old Food" for card in tokens)==1


