    while state["stack"]:state=perform_action(state,"player",{"type":"resolve"})
    player=next(p for p in state["players"] if p["id"]=="player");tokens=[card for card in player["battlefield"] if card.get("token")];assert any(card["type_line"]=="Token Creature — Detective" and set(card["colors"])=={"W","U"} for card in tokens);assert any(card["type_line"]=="Token Artifact Creature — Gnome" for card in tokens);assert next(card for card in player["battlefield"] if card["instance_id"]=="mausoleum-harpy")["counters"]["+1/+1"]==1


