def test_radiant_destiny_requires_a_type_choice_and_grants_its_tribal_effects():
    state=kept_game();player=next(p for p in state["players"] if p["id"]=="player");soldiers=[{**card(2790+index,f"Radiant Soldier {index}","Creature — Human Soldier","","2","2"),"instance_id":f"radiant-soldier-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(2)];merfolk={**card(2792,"Radiant Merfolk","Creature — Merfolk Wizard","","2","2"),"instance_id":"radiant-merfolk","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};destiny={**card(2793,"Radiant Destiny","Enchantment","{2}{W}"),"oracle_text":"Ascend\nAs this enchantment enters, choose a creature type.\nCreatures you control of the chosen type get +1/+1. As long as you have the city's blessing, they also have vigilance.","instance_id":"radiant-destiny","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False};player["battlefield"]=[*soldiers,merfolk];_enter_battlefield(state,player,[destiny]);action=next(action for action in legal_actions(state,"player") if action["type"]=="choose_creature_type");assert {"Human","Soldier","Merfolk","Wizard"}.issubset(set(action["suggested_types"]))
