    lands=[{**card(2794+index,"Plains","Basic Land — Plains"),"instance_id":f"radiant-plains-{index}","owner_id":"player","controller_id":"player","tapped":False,"damage":0,"counters":{},"summoning_sick":False} for index in range(6)];_enter_battlefield(state,player,lands);assert player["city_blessing"] and all(_has_keyword(card,"Vigilance") for card in soldiers) and not _has_keyword(merfolk,"Vigilance");_leave_battlefield(state,player,destiny,"graveyard");assert all(_parse_stats(card,state)==(2,2) and not _has_keyword(card,"Vigilance") for card in soldiers)


